// =============================================================================
// verify-cfs — node "Formatage résultats"  (Code — Run Once for All Items)   v3
//
// Correctif v3 : le verdict ne se calculait que sur les checks `blocking:true`.
// Un KPI non documenté (MISSING) ou un écart non bloquant disparaissait donc du
// verdict, qui affichait PASS alors que le détail montrait un ⚠️ ou un ❌.
//
// Règle appliquée maintenant :
//   FAIL            : au moins un check BLOQUANT en FAIL
//   PASS_WITH_GAPS  : sinon, au moins un FAIL non bloquant, ou un MISSING/UNPARSABLE
//   PASS            : tous les checks en PASS
// =============================================================================

const GEN = 'Generation_SPARQL';

function extractRows(resp) {
  if (!resp) return [];
  if (Array.isArray(resp)) return resp;
  if (Array.isArray(resp.results)) return resp.results;
  if (resp.results && Array.isArray(resp.results.bindings)) return resp.results.bindings;
  if (Array.isArray(resp.bindings)) return resp.bindings;
  if (Array.isArray(resp.data)) return resp.data;
  if (resp.data && Array.isArray(resp.data.results)) return resp.data.results;
  return [];
}
const val = x => (x && typeof x === 'object' && 'value' in x) ? x.value : x;
const short = uri => String(uri ?? '').split(/[\/#]/).pop();

// v4 : statuts supplémentaires produits par une requête fournie par l'appelant
//      (conversion d'unité à partir de tmf:unitOfMeasure)
const GAP_STATUSES = ['MISSING', 'UNPARSABLE', 'MISSING_UNIT', 'UNKNOWN_UNIT'];
const ICON = { PASS: '✅', FAIL: '❌', MISSING: '⚠️', UNPARSABLE: '⚠️', MISSING_UNIT: '⚠️', UNKNOWN_UNIT: '⚠️' };
const TXT  = { PASS: 'conforme', FAIL: 'non conforme', MISSING: 'non documenté dans l’ontologie',
               UNPARSABLE: 'valeur illisible dans l’ontologie',
               MISSING_UNIT: 'unité absente dans l’ontologie (comparaison impossible)',
               UNKNOWN_UNIT: 'unité inconnue du convertisseur (comparaison impossible)' };

const genItems = $(GEN).all().map(i => i.json);
const inItems  = $input.all();
const out = [];

for (let k = 0; k < inItems.length; k++) {
  const resp = inItems[k].json || {};
  const gen = genItems.find(g => g.ref && resp.ref && String(g.ref) === String(resp.ref))
           || genItems[k] || {};
  const reqs = Array.isArray(gen.requirements) ? gen.requirements : [];
  const ref  = gen.ref ?? resp.ref ?? null;

  if (gen.skip || resp.skip) {
    out.push({ json: { ref, candidateId: gen.candidateId ?? null, verdict: 'SKIPPED',
      skip_reason: gen.skip_reason ?? 'skip', error: gen.error ?? null, checks: [], satisfied: [],
      unsatisfied: [], soft_unsatisfied: [], undocumented: [],
      message: 'Vérification ontologique non effectuée (' + (gen.skip_reason || 'skip') + ').' } });
    continue;
  }

  const rows = extractRows(resp);
  if (!rows.length) {
    out.push({ json: { ref, candidateId: gen.candidateId ?? null, verdict: 'ERROR',
      error: 'AUCUNE_LIGNE_RETOURNEE', checks: [], satisfied: [], unsatisfied: [],
      soft_unsatisfied: [], undocumented: [], raw_response_keys: Object.keys(resp),
      message: 'Impossible de vérifier : l’ontologie n’a retourné aucune ligne pour ce CFS. Vérifiez l’identifiant du candidat.' } });
    continue;
  }

  const perCandidate = rows.map(row => {
    const checks = reqs.map((r, i) => {
      const status = val(row['status' + i]) ?? 'MISSING';
      return {
        kpi: r.kpi,
        label: r.label || r.kpi,
        op: r.op,
        expected: r.value,
        unit: r.unit || '',
        actual: val(row['value' + i]) ?? null,
        status,
        blocking: r.blocking !== false,
        source_key: r.source_key ?? null,
        source_value: r.source_value ?? null,
      };
    });
    // --- verdict : TOUS les checks comptent, le caractère bloquant ne change que la gravité ---
    const hardFail = checks.some(c => c.blocking && c.status === 'FAIL');
    const softFail = checks.some(c => !c.blocking && c.status === 'FAIL');
    const gaps     = checks.some(c => GAP_STATUSES.includes(c.status));
    const verdict  = hardFail ? 'FAIL' : (softFail || gaps) ? 'PASS_WITH_GAPS' : 'PASS';
    const score    = checks.filter(c => c.status === 'PASS').length;
    const gapCount = checks.filter(c => c.status !== 'PASS').length;
    return { candidate: val(row.candidate), checks, verdict, score, gapCount };
  });

  const ORDRE = { PASS: 0, PASS_WITH_GAPS: 1, FAIL: 2 };
  perCandidate.sort((a, b) => (ORDRE[a.verdict] - ORDRE[b.verdict])
    || (b.score - a.score) || (a.gapCount - b.gapCount));
  const best = perCandidate[0];

  const satisfied       = best.checks.filter(c => c.status === 'PASS').map(c => c.label);
  const unsatisfied     = best.checks.filter(c => c.status === 'FAIL' && c.blocking).map(c => c.label);
  const softUnsatisfied = best.checks.filter(c => c.status === 'FAIL' && !c.blocking).map(c => c.label);
  const undocumented    = best.checks.filter(c => GAP_STATUSES.includes(c.status))
    .map(c => c.label + (c.status === 'MISSING' ? '' : ` [${c.status}]`));

  const ligne = c => `  • ${c.label} : exigé ${c.op} ${c.expected}${c.unit ? ' ' + c.unit : ''}`
    + ` / offert ${c.actual ?? '—'} → ${ICON[c.status] || ''} ${TXT[c.status] || c.status}`
    + (c.status === 'FAIL' && !c.blocking ? ' (non bloquant)' : '');

  const detail = best.checks.map(ligne).join('\n');
  let message;
  if (best.verdict === 'PASS') {
    message = '✅ Le CFS proposé satisfait toutes vos exigences vérifiées :\n' + detail;
  } else if (best.verdict === 'PASS_WITH_GAPS') {
    const reste = [];
    if (softUnsatisfied.length) reste.push('écart non bloquant sur ' + softUnsatisfied.join(', '));
    if (undocumented.length)    reste.push('non documenté au catalogue : ' + undocumented.join(', '));
    message = '🟠 Le CFS proposé ne contredit aucune exigence bloquante, mais tout n’est pas garanti :\n'
      + detail + '\n\nÀ confirmer auprès de l’opérateur — ' + reste.join(' ; ') + '.';
  } else {
    message = '❌ Le CFS proposé ne satisfait pas toutes vos exigences.\n\nDétail :\n' + detail
      + '\n\nExigences non satisfaites : ' + unsatisfied.join(', ') + '.';
  }

  out.push({ json: {
    ref, candidateId: short(best.candidate) || gen.candidateId || null,
    verdict: best.verdict, checks: best.checks,
    satisfied, unsatisfied, soft_unsatisfied: softUnsatisfied, undocumented, message,
    ranking: perCandidate.map(c => ({ candidate: short(c.candidate), verdict: c.verdict, score: c.score })),
  } });
}

return out;

// =============================================================================
// verify-cfs v2 — node "Generation_SPARQL"  (Code — Run Once for All Items)
//
// Changements vs v1 :
//  1. traite TOUS les items (v1 ne traitait que $json = le 1er item) -> vérification
//     de plusieurs capacités / plusieurs candidats en un seul appel ;
//  2. candidateId peut être une chaîne OU un tableau -> VALUES ?candidate (classement top-K) ;
//  3. sous-SELECT + SAMPLE par KPI : plus de produit cartésien si un CFS porte
//     plusieurs valeurs pour une même caractéristique ;
//  4. cast numérique robuste (virgule décimale, unité collée : "10 ms", "99,999 %") ;
//  5. nouvel opérateur "contains" pour les chaînes (areaOfService = "Toulouse, Blagnac") ;
//  6. ne lève plus d'exception : renvoie skip=true / error -> le pipeline parent
//     ne casse jamais sur une vérification impossible ;
//  7. ?overall n'est plus calculé en SPARQL (une erreur d'évaluation y rendait la
//     variable non liée) : le verdict est calculé en JS dans le node de formatage.
//
// Entrées attendues par item : candidateId (string|array), requirements (array|string JSON), ref
// Sortie : { ref, candidateId, candidates[], requirements[], sparql, skip, error }
// =============================================================================

// ─────────────────────────────────────────────────────────────────────────────
// v4 : PASSE-PLAT. Si le workflow appelant fournit déjà `sparql`, on l'utilise
// tel quel : c'est lui qui connaît les noms exacts des caractéristiques, les
// unités (tmf:unitOfMeasure) et les codes de zone du catalogue.
// Sans `sparql`, le comportement de v3 s'applique intégralement (REGISTRY).
// ─────────────────────────────────────────────────────────────────────────────
const PREBUILT = (() => {
  const out = [];
  for (const item of $input.all()) {
    const j = item.json || {};
    const pre = String(j.sparql ?? '').trim();
    if (!pre) { out.push(null); continue; }
    const cand = String(j.candidateId ?? '').trim();
    out.push({ json: {
      ref: j.ref ?? j.functionality_id ?? null,
      skip: false, skip_reason: null, error: null,
      candidateId: cand || null,
      candidates: cand ? [cand] : [],
      requirements: (() => { let v = j.requirements;
        for (let i = 0; i < 3 && typeof v === 'string'; i++) { try { v = JSON.parse(v); } catch (_) { break; } }
        return Array.isArray(v) ? v : []; })(),
      sparql: pre,
      sparql_source: 'caller',
    } });
  }
  return out;
})();

const REGISTRY = {
  'latency': {kind:'number'}, 'reliability': {kind:'number'}, 'availability': {kind:'number'},
  'Maximum number of UEs': {kind:'number'}, 'UE density': {kind:'number'},
  'downlinkThroughputPerUE': {kind:'number'}, 'Downlink Throughput': {kind:'number'},
  'Uplink Throughput': {kind:'number'},
  'isolationLevel': {kind:'string'}, 'uEMobilityLevel': {kind:'string'}, 'areaOfService': {kind:'string'},
};
const NUMERIC_OPS = new Set(['=','!=','<','<=','>','>=']);
const STRING_OPS  = new Set(['=','!=','contains']);
const BASE = 'http://vocab.nfmust.ie/tmf-service-core/concret_cfs/';
const PREFIXES =
  'PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>\n' +
  'PREFIX tmf: <http://vocab.nfmust.ie/tmf-service-core#>';

const esc = s => String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"');

function parseLlmJson(raw) {
  if (raw && typeof raw === 'object') return raw;
  let s = String(raw).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  if (s[0] !== '{' && s[0] !== '[') { const m = s.match(/[\{\[][\s\S]*[\}\]]/); if (m) s = m[0]; }
  return JSON.parse(s);
}
function normalizeRequirements(value) {
  let v = value;
  for (let i = 0; i < 3 && typeof v === 'string'; i++) { try { v = parseLlmJson(v); } catch (_) { break; } }
  if (v && typeof v === 'object' && !Array.isArray(v) && Array.isArray(v.requirements)) v = v.requirements;
  return Array.isArray(v) ? v : [];
}
const toUri = id => (/^https?:\/\//.test(id) ? id : BASE + id);

// Extraction numérique tolérante côté SPARQL :
//   "99,999 %" -> "99.999" ; "10 ms" -> "10" ; "50 Mbit/s" -> "50"
function numExpr(varName) {
  // xsd:double et non xsd:decimal : decimal rejette la notation scientifique ("1.0E-6")
  return `xsd:double(REPLACE(REPLACE(REPLACE(STR(?${varName}), ",", "."), "[^0-9.eE+-]", ""), "^([+-]?[0-9]*\\\\.?[0-9]+([eE][+-]?[0-9]+)?).*$", "$1"))`;
}

function buildQuery(candidates, requirements) {
  const valuesLine = '  VALUES ?candidate { ' + candidates.map(c => `<${toUri(c)}>`).join(' ') + ' }';
  const projected  = ['?candidate'];
  const body       = [valuesLine];

  requirements.forEach((r, i) => {
    const meta = REGISTRY[r.kpi];
    if (!meta) throw new Error(`KPI inconnu "${r.kpi}".`);
    const raw = `raw${i}`, num = `num${i}`;
    const nameV = `name${i}`, valV = `value${i}`, stV = `status${i}`;
    projected.push(`?${nameV} ?${valV} ?${stV}`);

    let test, numBind = '';
    if (meta.kind === 'number') {
      if (!NUMERIC_OPS.has(r.op)) throw new Error(`Opérateur "${r.op}" invalide pour le KPI numérique "${r.kpi}".`);
      const n = Number(r.value);
      if (!Number.isFinite(n)) throw new Error(`Valeur "${r.value}" non numérique pour "${r.kpi}".`);
      numBind = `  BIND(${numExpr(raw)} AS ?${num})`;
      test = `IF(!BOUND(?${num}), "UNPARSABLE", IF(?${num} ${r.op} ${n}, "PASS", "FAIL"))`;
    } else {
      if (!STRING_OPS.has(r.op)) throw new Error(`Opérateur "${r.op}" invalide pour le KPI textuel "${r.kpi}" (=, != ou contains).`);
      const lit = esc(String(r.value));
      const cmp = r.op === 'contains'
        ? `CONTAINS(LCASE(STR(?${raw})), LCASE("${lit}"))`
        : `LCASE(STR(?${raw})) ${r.op} LCASE("${lit}")`;
      test = `IF(${cmp}, "PASS", "FAIL")`;
    }

    body.push(
      `  OPTIONAL {`,
      `    SELECT ?candidate (SAMPLE(?v${i}) AS ?${raw}) WHERE {`,
      valuesLine.replace(/^ {2}/, '      '),
      `      ?candidate tmf:hasCharacteristic ?c${i} .`,
      `      ?c${i} tmf:name ?n${i} . FILTER(LCASE(STR(?n${i})) = LCASE("${esc(r.kpi)}"))`,
      `      ?c${i} tmf:hasCharacteristicValue ?cv${i} .`,
      `      ?cv${i} tmf:value ?v${i} .`,
      `    } GROUP BY ?candidate`,
      `  }`,
    );
    if (numBind) body.push(numBind);
    body.push(
      `  BIND("${esc(r.kpi)}" AS ?${nameV})`,
      `  BIND(?${raw} AS ?${valV})`,
      `  BIND(IF(!BOUND(?${raw}), "MISSING", ${test}) AS ?${stV})`,
    );
  });

  return `${PREFIXES}\nSELECT ${projected.join(' ')}\nWHERE {\n${body.join('\n')}\n}`;
}

// ── Traitement de TOUS les items ─────────────────────────────────────────────
// NB : les items "skip" reçoivent une requête no-op au lieu de null. Raison :
// router les skips autour du node HTTP via un IF ferait exécuter le node de
// formatage DEUX fois (une par branche entrante) et casserait l'appariement
// 1 item d'entrée -> 1 item de sortie. Une requête triviale coûte moins cher
// qu'un branchement qui casse le contrat.
const NOOP_SPARQL = 'SELECT ?skip WHERE { BIND("skip" AS ?skip) }';
const out = [];
const ALL = $input.all();
for (let k = 0; k < ALL.length; k++) {
  const item = ALL[k];
  if (PREBUILT[k]) { out.push(PREBUILT[k]); continue; }   // v4 : requête fournie par l'appelant
  const input = item.json || {};
  const ref = input.ref ?? input.functionality_id ?? null;

  const rawId = input.candidateId ?? input.candidates ?? input.spec_id ?? null;
  const candidates = (Array.isArray(rawId) ? rawId : [rawId])
    .filter(x => x !== null && x !== undefined && String(x).trim() !== '')
    .map(String);
  const requirements = normalizeRequirements(input.requirements);

  if (!candidates.length) {
    out.push({ json: { ref, skip: true, skip_reason: 'no_candidate', candidateId: null,
                       candidates: [], requirements, sparql: NOOP_SPARQL } });
    continue;
  }
  if (!requirements.length) {
    out.push({ json: { ref, skip: true, skip_reason: 'no_requirements', candidateId: candidates[0],
                       candidates, requirements: [], sparql: NOOP_SPARQL } });
    continue;
  }
  try {
    out.push({ json: { ref, skip: false, candidateId: candidates[0], candidates, requirements,
                       sparql: buildQuery(candidates, requirements) } });
  } catch (e) {
    out.push({ json: { ref, skip: true, skip_reason: 'build_error', error: String(e.message || e),
                       candidateId: candidates[0], candidates, requirements, sparql: NOOP_SPARQL } });
  }
}
return out;
